mapper.select:
SELECT al.audit_id, al.admin_id, al.target_table, al.target_pk, al.before_value, al.after_value,
al.reason_code, al.processed_at, au.name AS admin_name, au.role AS admin_role
FROM audit_log al
LEFT JOIN admin_user au ON au.admin_id = al.admin_id

    AND al.admin_id = #{adminId}
    AND al.target_table = #{targetTable}
    AND al.target_pk = #{targetPk}
    AND al.reason_code = #{reasonCode}
    AND al.processed_at >= #{startDate}
    AND al.processed_at <= #{endDate}

ORDER BY al.processed_at DESC
